import {escapeHTML as e, utc, seconds, frameLabel, identifyControls, preserveFocus} from './investigation.js';
const states=new Map();
const storageKey=id=>`airframe.validation.v1.${id}`;
function initial(ctx,incident){let saved=null;try{saved=JSON.parse(localStorage.getItem(storageKey(incident.id))||'null');}catch{}const sameContext=saved?.context?.mode===incident.context.mode&&saved?.context?.cutoffUs===incident.context.cutoffUs;return {snapshot:structuredClone(incident),snapshotContext:{...incident.context},source:'all',selected:ctx.selectedFrameId||incident.anchors.deauth.id,expanded:false,saved:!!saved,saveError:false,plan:saved?.plan||{objective:'Collect controller evidence and assess comparable recorded exposure',note:'No infrastructure change performed.',duration:'60',minimum:'10',criteria:'No repeated deauthentication during eligible observed exposure.',abort:'Stop comparison if coverage or identity cannot be established.',owner:''},validation:sameContext?saved?.validation||null:null};}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function renderAction(container,ctx){
 const latest=ctx.service.getIncident(ctx.incidentId,ctx.context);
 if(!latest){container.innerHTML='<section class="panel empty-state"><h1>Evidence not yet available</h1><p>This incident is outside the current replay cutoff.</p><button class="btn" data-back>Return to investigation</button></section>';container.querySelector('[data-back]').onclick=ctx.onBack;return;}
 let state=states.get(latest.id);if(!state){state=initial(ctx,latest);states.set(latest.id,state);}
 if(state.snapshotContext.mode!==ctx.context.mode||state.snapshotContext.generation!==ctx.context.generation||ctx.context.mode==='capture_replay'&&state.snapshotContext.cutoffUs>ctx.context.cutoffUs){state.snapshot=structuredClone(latest);state.snapshotContext={...latest.context};state.validation=null;}
 const incident=state.snapshot,rows=incident.evidence||[];
 if(ctx.selectedFrameId&&ctx.selectedFrameId!==state.lastExternalFrame&&rows.some(f=>f.id===ctx.selectedFrameId)){state.selected=ctx.selectedFrameId;state.lastExternalFrame=ctx.selectedFrameId;}
 if(!rows.some(f=>f.id===state.selected))state.selected=incident.anchors.deauth.id;
 const selected=rows.find(f=>f.id===state.selected)||incident.anchors.deauth;
 const allFiltered=rows.filter(f=>state.source==='all'||f.source===state.source);
 const anchors=new Set(Object.values(incident.anchors).filter(Boolean).map(f=>f.id));
 const filtered=state.allObservations?allFiltered.slice((state.eventPage||0)*20,((state.eventPage||0)+1)*20):allFiltered.filter(f=>anchors.has(f.id)||f.id===state.selected);
 const newer=(latest.evidence?.length||0)>rows.length||latest.lifecycle!==incident.lifecycle;
 const observed=incident.durationUs==null?'A deauthentication frame is observed. No subsequent successful association response is visible in this snapshot.':`A deauthentication frame preceded a successful association response after ${seconds(incident.durationUs)} of recorded protocol time.`;
 const plan=state.plan;
 const baselineEndUs=incident.endUs||state.snapshotContext.cutoffUs;
 const windowSummary=`<dl class="ws-window-summary"><div><dt>Baseline · observed sequence</dt><dd>${utc(incident.openUs,true)}–${utc(baselineEndUs,true)} UTC</dd></div><div><dt>Proposed forward window</dt><dd data-forward-window>${utc(baselineEndUs,true)}–${utc(baselineEndUs+Number(plan.duration)*1000000,true)} UTC · ${e(plan.duration)} seconds</dd></div><div><dt>Eligible exposure</dt><dd data-exposure-summary>At least ${e(plan.minimum)} relevant observations for ${e(incident.client)}, with verified identity and comparable channel coverage.</dd></div></dl><p class="ws-comparison-prerequisites"><strong>Prerequisites not established:</strong> complete forward-window membership, sensor/capture health, and comparable operating conditions. The current incident selection cannot certify the comparison. Saving a plan does not start live monitoring.</p>`;
 container.innerHTML=`<div class="action-view"><div class="ws-action-context"><div class="ws-action-breadcrumb"><button class="ws-link" data-back>${e(incident.id)}</button><span> / Action brief</span></div><section class="panel ws-event-list"><div class="ws-evidence-heading"><h2>⌁ Event timeline</h2><select data-action-source aria-label="Filter action timeline by source"><option value="all">All sources</option>${[...new Set(rows.map(f=>f.source))].sort().map(s=>`<option ${s===state.source?'selected':''}>${e(s)}</option>`).join('')}</select></div><div class="ws-action-events">${filtered.map(f=>`<button class="ws-action-event ${f.id===state.selected?'is-selected':''} ${f.id===incident.anchors.deauth.id?'attention':f.id===incident.anchors.association?.id?'association':'evidence'}" data-select="${e(f.id)}"><span class="ws-event-dot"></span><time class="mono">${utc(f.timeUs)}</time><span class="mono">${e(f.source)}</span><span>${e(f.type)}${f.retry?' (retry)':''}</span></button>`).join('')||'<p class="ws-empty">No matching observations.</p>'}</div><p class="ws-notice">${filtered.length} observations · Recorded time; clocks unverified</p></section><section class="panel ws-selected-frame"><div class="ws-evidence-heading"><h2>${e(selected.id)} · ${e(selected.type)}</h2></div><p class="mono muted">${utc(selected.timeUs,true)} UTC</p><dl>${[['Source',selected.source],['Client',incident.client],['Logical BSSID',selected.bssid||incident.ap],['Transmitter',selected.transmitter],['Receiver',selected.receiver],['Channel',selected.channel],['Signal at source',selected.signal==null?'Unavailable':`${selected.signal} dBm`],['Reason code',selected.reasonCode??'Not applicable'],['Status code',selected.statusCode??'Not applicable'],['Original frame',selected.frameNumber]].map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value??'Unavailable')}</dd></div>`).join('')}</dl><button class="ws-link" data-full-frame>Open full frame provenance ↗</button></section></div>
 <section class="panel ws-brief"><div class="ws-brief-heading"><h1>Action brief</h1><span class="chip ws-attention">⚠ Human review required</span><button class="ws-close" aria-label="Close action brief" data-close>×</button></div>${newer?'<div class="ws-newer">Newer evidence is available. This brief remains frozen.<button class="btn" data-refresh>Refresh snapshot</button></div>':''}<div class="ws-brief-observed"><h2>Observed</h2><p>${e(observed)}</p><h2>Cause</h2><p class="ws-cause">Unresolved</p><p class="muted">Packet headers do not explain the AP decision.</p><div class="ws-grades"><div><span class="ws-grade-icon">▤</span><span><small>Evidence completeness</small><strong>Partial</strong></span></div><div><span class="ws-grade-icon">▥</span><span><small>Hypothesis confidence</small><strong>Unresolved</strong></span></div></div><p class="ws-notice">⚠ Sensor health and cross-source clock alignment are unverified.</p></div>
 <section class="ws-next-steps"><h2>Next steps</h2><ol><li><span>1</span><div><strong>Inspect AP/controller records</strong><p>${e(incident.ap)} · ${utc(incident.openUs)} UTC · Account for unknown clock alignment.</p></div></li><li><span>2</span><div><strong>Compare channel observations</strong><p>Check retry activity and capture coverage before changing RF configuration.</p></div></li><li><span>3</span><div><strong>Record a proposed change and comparison criteria</strong><p>Require operator approval, a maintenance window, and a rollback plan.</p></div></li></ol></section>
 <section class="ws-validation"><div class="ws-evidence-heading"><h2>Validation plan</h2><span class="chip">Offline comparison</span></div><p class="ws-notice">Recorded evidence only. No live feed or infrastructure control is connected.</p><form data-plan-form><div class="ws-plan-summary"><label>Objective<input name="objective" value="${e(plan.objective)}" required></label><label>Change / no-change note<textarea name="note" rows="2" required>${e(plan.note)}</textarea></label></div><details ${state.expanded?'open':''} data-plan-details><summary>Comparison criteria & safeguards</summary><div class="ws-plan-grid"><label>Forward window (seconds)<input type="number" name="duration" min="1" max="1800" value="${e(plan.duration)}" required></label><label>Minimum relevant observations<input type="number" name="minimum" min="1" max="100000" value="${e(plan.minimum)}" required></label><label class="ws-span-two">Success criterion<textarea name="criteria" required>${e(plan.criteria)}</textarea></label><label class="ws-span-two">Abort criterion<textarea name="abort" required>${e(plan.abort)}</textarea></label><label class="ws-span-two">Owner (optional)<input name="owner" value="${e(plan.owner)}"></label></div></details><div class="ws-plan-status"><span>Status</span><span class="chip">${state.validation?'Insufficient evidence':'Draft'}</span><span class="muted" data-save-label>${state.saveError?'Not saved · storage unavailable':state.saved?'Saved locally':'Unsaved changes'}</span></div>${state.validation?`<div class="ws-comparison-result" role="status"><strong>Inconclusive · insufficient evidence</strong><p>${e(state.validation.explanation)}</p><small>Origin: offline comparison · Snapshot ${utc(state.snapshotContext.cutoffUs||incident.endUs||incident.openUs)} UTC</small></div>`:''}<div class="ws-plan-actions"><button class="btn btn-primary" type="submit">Save validation plan</button><button class="btn" type="button" data-compare>Start offline comparison</button></div></form><div class="ws-export-row"><button class="btn" data-export>↓ Export evidence brief</button><p class="ws-notice">ⓘ Monitoring does not change infrastructure.</p></div></section></section></div>`;
 identifyControls(container,'action');
 container.querySelector('[data-plan-form]').insertAdjacentHTML('beforebegin',windowSummary);
 const redraw=()=>ctx.refresh?ctx.refresh():preserveFocus(container,()=>renderAction(container,ctx));
 const eventList=container.querySelector('.ws-event-list');eventList.insertAdjacentHTML('beforeend',`<div class="diag-pagination"><button class="btn" data-all-observations>${state.allObservations?'Decision anchors':'All observations'}</button>${state.allObservations?`<button class="btn" data-event-page="-1" ${state.eventPage?'':'disabled'}>Previous</button><span>Page ${(state.eventPage||0)+1}</span><button class="btn" data-event-page="1" ${((state.eventPage||0)+1)*20>=allFiltered.length?'disabled':''}>Next</button>`:''}</div>`);container.querySelector('[data-all-observations]').onclick=()=>{state.allObservations=!state.allObservations;state.eventPage=0;redraw();};container.querySelectorAll('[data-event-page]').forEach(b=>b.onclick=()=>{state.eventPage=(state.eventPage||0)+Number(b.dataset.eventPage);redraw();});
 container.querySelectorAll('[data-back],[data-close]').forEach(b=>b.onclick=ctx.onBack);
 container.querySelector('[data-action-source]').onchange=event=>{state.source=event.target.value;redraw();};
 container.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.select;redraw();});
 container.querySelector('[data-full-frame]').onclick=()=>ctx.onFrame(selected.id);
 container.querySelector('[data-refresh]')?.addEventListener('click',()=>{state.snapshot=structuredClone(latest);state.snapshotContext={...latest.context};state.validation=null;state.saved=false;redraw();ctx.notify('Brief refreshed to the latest visible evidence.');});
 container.querySelector('[data-plan-details]').ontoggle=event=>state.expanded=event.target.open;
 const form=container.querySelector('[data-plan-form]');
 form.querySelectorAll('input,textarea').forEach(input=>input.oninput=()=>{state.plan[input.name]=input.value;state.saved=false;container.querySelector('[data-save-label]').textContent='Unsaved changes';if(input.name==='duration')container.querySelector('[data-forward-window]').textContent=`${utc(baselineEndUs,true)}–${utc(baselineEndUs+Number(input.value)*1000000,true)} UTC · ${input.value} seconds`;if(input.name==='minimum')container.querySelector('[data-exposure-summary]').textContent=`At least ${input.value} relevant observations for ${incident.client}, with verified identity and comparable channel coverage.`;});
 const persist=()=>{try{localStorage.setItem(storageKey(incident.id),JSON.stringify({schemaVersion:'1.0',dataset:ctx.service.manifest.datasetId||ctx.service.manifest.dataset_id,incidentId:incident.id,context:state.snapshotContext,plan:state.plan,validation:state.validation,savedAt:new Date().toISOString()}));state.saved=true;state.saveError=false;ctx.notify('Validation plan saved on this device.');}catch{state.saved=false;state.saveError=true;ctx.notify('Storage unavailable. Your draft remains visible; export a copy.');}};
 form.onsubmit=event=>{event.preventDefault();if(!form.reportValidity())return;persist();redraw();};
 container.querySelector('[data-compare]').onclick=()=>{if(!form.reportValidity())return;const requiredUs=Number(plan.duration)*1000000;state.validation={origin:'offline_comparison',status:'insufficient_evidence',conclusion:'inconclusive',baselineStartUs:incident.openUs,baselineEndUs:incident.endUs||state.snapshotContext.cutoffUs,forwardDurationUs:requiredUs,minimumRelevantObservations:Number(plan.minimum),explanation:'This incident selection does not establish complete client exposure in a comparable forward window. Source health, packet loss and operating conditions are unverified. No criteria pass or physical improvement can be inferred.'};state.saved=false;redraw();ctx.notify('Offline comparison is inconclusive: comparable forward exposure is not verified.');};
 container.querySelector('[data-export]').onclick=()=>{try{const manifest={format:'airframe-evidence-brief',schemaVersion:'1.0',dataset:ctx.service.manifest,incidentId:incident.id,context:state.snapshotContext,origin:'offline_comparison',observed,cause:'Unresolved',evidenceGrade:'partial',hypothesisGrade:'unresolved',counts:{retryResponses:incident.retryCount,clientProbes:incident.probeCount,responseViewpoints:incident.viewpoints},evidence:rows,plan:state.plan,validation:state.validation,limitations:incident.limitations,exportedAt:new Date().toISOString()};const text=`AIRFRAME — ${incident.id} evidence brief\n\nMode: ${state.snapshotContext.mode}\nOrigin: offline comparison\nCutoff: ${state.snapshotContext.cutoffUs}\n\nOBSERVED\n${observed}\n\nCAUSE\nUnresolved. Packet headers do not establish a physical cause.\n\nEVIDENCE\n${rows.map(f=>`${f.id} | ${utc(f.timeUs,true)} UTC | ${frameLabel(f)} | ${f.source} | channel ${f.channel}`).join('\n')}\n\nVALIDATION PLAN\n${Object.entries(state.plan).map(([k,v])=>`${k}: ${v}`).join('\n')}\n\nLIMITATIONS\nSource health and cross-source clocks unverified. Illustrative physical placement. Association is not application recovery. Monitoring does not change infrastructure.\n\nMachine-readable snapshot follows:\n${JSON.stringify(manifest,null,2)}`;download(text,`${incident.id}-evidence-brief-${state.snapshotContext.generation||0}.txt`,'text/plain;charset=utf-8');ctx.notify('Evidence brief download prepared with its machine-readable snapshot.');}catch{ctx.notify('Could not prepare export. Your draft is retained; please retry.');}};
}
